import "./figure.css";

export interface FigureProps {
  src: string;
  alt: string;
  caption: string;
  credit: string;
  ratio: "16 / 9" | "3 / 2" | "4 / 3" | "1 / 1" | "21 / 9";
  width: "contained" | "wide" | "full bleed";
  radius: "none" | "soft" | "round";
  treatment: "color" | "b&w";
}

export function FigureRender({ src, alt, caption, credit, ratio, width, radius, treatment }: FigureProps) {
  const hasCap = Boolean(caption || credit);
  return (
    <figure className="p1-figure p1-block" data-width={width} data-radius={radius}>
      <div className="p1-figure__frame" style={{ aspectRatio: ratio }}>
        <img src={src} alt={alt} className="p1-figure__img" data-treatment={treatment} />
      </div>
      {hasCap && (
        <figcaption className="p1-figure__caption">
          <span className="p1-figure__caption-text">{caption}</span>
          {credit && <span className="p1-figure__credit">{credit}</span>}
        </figcaption>
      )}
    </figure>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { FigureRender, type FigureProps } from "./figure";
export type { FigureProps };

export const FigureBlock: ComponentConfig<FigureProps> = {
  fields: {
    src: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { exclude: true },
    },
    alt: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Alt text for the image. 1–2 sentences describing what is shown." },
    },
    caption: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A brief caption for the image. 1 sentence." },
    },
    credit: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Photo credit. Format: Photo — Source Name." },
    },
    ratio: {
      type: "select" as const,
      options: [
        { label: "16 / 9", value: "16 / 9" },
        { label: "3 / 2", value: "3 / 2" },
        { label: "4 / 3", value: "4 / 3" },
        { label: "1 / 1", value: "1 / 1" },
        { label: "21 / 9", value: "21 / 9" },
      ],
    },
    width: {
      type: "select" as const,
      options: [
        { label: "Contained", value: "contained" },
        { label: "Wide", value: "wide" },
        { label: "Full bleed", value: "full bleed" },
      ],
    },
    radius: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Soft", value: "soft" },
        { label: "Round", value: "round" },
      ],
    },
    treatment: {
      type: "radio" as const,
      options: [
        { label: "Color", value: "color" },
        { label: "B&W", value: "b&w" },
      ],
    },
  },
  defaultProps: {
    src: wireframe(1300, 731),
    alt: "The team reviewing a preview together",
    caption: "The team reviews a preview link before anything reaches Live.",
    credit: "Photo — Pantheon",
    ratio: "3 / 2",
    width: "wide",
    radius: "soft",
    treatment: "color",
  },
  render: FigureRender,
};

export const meta = defineMeta({
  title: 'Figure',
  description: 'Single image with optional caption and photo credit, supporting aspect ratio, width, radius, and b&w treatment; use for editorial images.',
  categories: ["editorial"],
  published: true,
});

.p1-figure {
  margin-inline: auto;
  padding-block: var(--p1-space-md);
}

.p1-figure[data-width="contained"] {
  max-inline-size: var(--p1-container-narrow);
  padding-inline: var(--p1-space-lg);
}
.p1-figure[data-width="wide"] {
  max-inline-size: var(--p1-container-default);
  padding-inline: var(--p1-space-lg);
}

.p1-figure__frame {
  background-color: color-mix(in oklch, var(--p1-surface-inverse) 8%, transparent);
  overflow: hidden;
}

.p1-figure[data-width="contained"] .p1-figure__frame,
.p1-figure[data-width="wide"] .p1-figure__frame {
  border: 1px solid var(--p1-border);
}

.p1-figure[data-radius="soft"] .p1-figure__frame { border-radius: var(--p1-radius-card); }
.p1-figure[data-radius="round"] .p1-figure__frame { border-radius: var(--p1-radius-xl); }

.p1-figure__img {
  block-size: 100%;
  inline-size: 100%;
  object-fit: cover;
}
.p1-figure__img[data-treatment="b&w"] { filter: grayscale(1); }

.p1-figure__caption {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: var(--p1-space-md);
  justify-content: space-between;
  margin-block-start: var(--p1-space-sm);
}
.p1-figure[data-width="full bleed"] .p1-figure__caption {
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
  padding-inline: var(--p1-space-lg);
}

.p1-figure__caption-text {
  color: var(--p1-fg-muted);
  flex: 1;
  font-size: var(--p1-text-sm);
  line-height: var(--p1-leading-normal);
}
.p1-figure__credit {
  color: var(--p1-fg-muted);
  flex: none;
  font-size: var(--p1-text-sm);
  font-style: italic;
  opacity: 0.75;
}

